const DumbbellScale: React.FC<DumbbellScaleProps> = ({
  backgroundColor = "#f4f1ea",
  transparentBackground = false,
  durationInSeconds = 8,
  primaryColor = "#0b3b82",
  dumbbellWeightColor = "#222222",
  scaleSize = 1.0,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();

  // Responsive scaling factor based on optimal 1920x1080 canvas
  const scaleFactor = Math.min(width, height) / 1000;

  // Setup fluid, proportional checkpoints for the animation sequence
  const landDumbbellFrame = Math.round(durationInFrames * 0.12); // Dumbbell lands early
  const startSobrietyFallFrame = Math.round(durationInFrames * 0.40); // Sobriety starts falling
  const landSobrietyFrame = Math.round(durationInFrames * 0.52); // Sobriety lands

  // Mathematical tilt angle based on current state & spring dynamics
  const angle = (() => {
    if (frame < landDumbbellFrame) {
      return 0;
    }
    if (frame < landSobrietyFrame) {
      // Step 1: Dumbbell lands -> scale tips to the left (negative angle)
      const leftTiltSpring = spring({
        frame: frame - landDumbbellFrame,
        fps,
        config: { mass: 0.9, damping: 11, stiffness: 85 },
      });
      return interpolate(leftTiltSpring, [0, 1], [0, -11.5]);
    }
    // Step 2: Sobriety lands -> scale tips fully to the right (positive angle)
    const rightTiltSpring = spring({
      frame: frame - landSobrietyFrame,
      fps,
      config: { mass: 1.4, damping: 14, stiffness: 45 },
    });
    return interpolate(rightTiltSpring, [0, 1], [-11.5, 11.5]);
  })();

  // Entry gravity drop offsets (quadratic ease-in to simulate natural acceleration)
  const dumbbellProgress = Math.min(1, frame / landDumbbellFrame);
  const dumbbellYOffset = frame < landDumbbellFrame
    ? (1 - dumbbellProgress * dumbbellProgress) * (height * 0.6)
    : 0;

  const sobrietyDuration = landSobrietyFrame - startSobrietyFallFrame;
  const sobrietyProgress = Math.min(1, Math.max(0, (frame - startSobrietyFallFrame) / sobrietyDuration));
  const sobrietyYOffset = frame < startSobrietyFallFrame
    ? height * 0.6
    : frame < landSobrietyFrame
      ? (1 - sobrietyProgress * sobrietyProgress) * (height * 0.6)
      : 0;

  // Smooth opacity fade-in as Sobriety approaches the scale
  const sobrietyOpacity = interpolate(
    frame,
    [startSobrietyFallFrame, startSobrietyFallFrame + Math.round(sobrietyDuration * 0.6)],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Geometric calculations for scale beam and endpoints
  const pivotX = width * 0.5;
  const pivotY = height * 0.58;
  const barLength = width * 0.60 * scaleSize;
  const barThickness = height * 0.018 * scaleSize;

  const angleInRadians = (angle * Math.PI) / 180;
  
  // Pivot coordinate positions
  const leftPanX = pivotX - (barLength / 2) * Math.cos(angleInRadians);
  const leftPanY = pivotY - (barLength / 2) * Math.sin(angleInRadians);

  const rightPanX = pivotX + (barLength / 2) * Math.cos(angleInRadians);
  const rightPanY = pivotY + (barLength / 2) * Math.sin(angleInRadians);

  // Custom adaptive background styling
  const bgStyle = transparentBackground
    ? { backgroundColor: "transparent" }
    : {
        background: `radial-gradient(circle at 50% 45%, ${backgroundColor} 0%, rgba(200,195,180,0.4) 100%)`,
        backgroundColor,
      };

  return (
    <AbsoluteFill style={{ ...bgStyle, overflow: "hidden" }}>
      {/* Ground shadows for spatial occlusion */}
      <div
        style={{
          position: "absolute",
          bottom: height * 0.12,
          left: width * 0.5,
          transform: "translateX(-50%)",
          width: width * 0.8 * scaleSize,
          height: height * 0.07,
          background: "radial-gradient(ellipse, rgba(0,0,0,0.12) 0%, rgba(0,0,0,0) 75%)",
          pointerEvents: "none",
          transition: "none",
        }}
      />

      {/* 1. Scale Pivot Base */}
      <svg
        style={{
          position: "absolute",
          left: pivotX - width * 0.1,
          top: pivotY,
          width: width * 0.2,
          height: height * 0.35,
          overflow: "visible",
          transition: "none",
        }}
      >
        <polygon
          points={`
            ${width * 0.1 - width * 0.015 * scaleSize},0
            ${width * 0.1 + width * 0.015 * scaleSize},0
            ${width * 0.1 + width * 0.08 * scaleSize},${height * 0.28 * scaleSize}
            ${width * 0.1 - width * 0.08 * scaleSize},${height * 0.28 * scaleSize}
          `}
          fill="#2a2a2a"
          style={{ filter: "drop-shadow(0px 8px 16px rgba(0,0,0,0.16))", transition: "none" }}
        />
      </svg>

      {/* 2. Rotating Balance Bar */}
      <div
        style={{
          position: "absolute",
          left: pivotX,
          top: pivotY,
          width: barLength,
          height: barThickness,
          backgroundColor: "#1f1f1f",
          borderRadius: barThickness / 2,
          transform: `translate(-50%, -50%) rotate(${angle}deg)`,
          boxShadow: "0 4px 8px rgba(0,0,0,0.25), inset 1px 1px 2px rgba(255,255,255,0.12)",
          zIndex: 1,
          transition: "none",
        }}
      />

      {/* 3. Center Pivot Caps (overlays on top of bar) */}
      <div
        style={{
          position: "absolute",
          left: pivotX,
          top: pivotY,
          width: 50 * scaleFactor * scaleSize,
          height: 50 * scaleFactor * scaleSize,
          transform: "translate(-50%, -50%)",
          zIndex: 10,
          transition: "none",
        }}
      >
        <svg width="100%" height="100%" viewBox="0 0 50 50">
          <circle
            cx="25"
            cy="25"
            r={20 * scaleSize}
            fill="#e2e8f0"
            stroke="#64748b"
            strokeWidth={2}
          />
          <circle
            cx="25"
            cy="25"
            r={10 * scaleSize}
            fill="#94a3b8"
          />
        </svg>
      </div>

      {/* 4. Left Platform & Dumbbell (keeps perfectly level) */}
      <div
        style={{
          position: "absolute",
          left: leftPanX,
          top: leftPanY,
          width: width * 0.22,
          height: height * 0.35,
          transform: "translate(-50%, -90%)",
          display: "flex",
          flexDirection: "column",
          justifyContent: "flex-end",
          alignItems: "center",
          zIndex: 2,
          transition: "none",
        }}
      >
        {/* Falling/Resting Dumbbell */}
        <div
          style={{
            transform: `translateY(${-dumbbellYOffset}px)`,
            opacity: frame >= 1 ? 1 : 0,
            marginBottom: height * 0.012,
            transition: "none",
          }}
        >
          <Dumbbell weightColor={dumbbellWeightColor} scale={scaleFactor * scaleSize} />
        </div>

        {/* Pan Dish */}
        <Pan width={width * 0.165 * scaleSize} height={height * 0.042 * scaleSize} />
      </div>

      {/* 5. Right Platform & 'SOBRIETY' Word (keeps perfectly level) */}
      <div
        style={{
          position: "absolute",
          left: rightPanX,
          top: rightPanY,
          width: width * 0.26,
          height: height * 0.35,
          transform: "translate(-50%, -90%)",
          display: "flex",
          flexDirection: "column",
          justifyContent: "flex-end",
          alignItems: "center",
          zIndex: 2,
          transition: "none",
        }}
      >
        {/* Falling/Resting 'SOBRIETY' text */}
        <div
          style={{
            transform: `translateY(${-sobrietyYOffset}px)`,
            opacity: sobrietyOpacity,
            marginBottom: height * 0.015,
            transition: "none",
          }}
        >
          <span
            style={{
              fontFamily: barlowFamily,
              fontSize: 84 * scaleFactor * scaleSize,
              fontWeight: 900,
              color: primaryColor,
              letterSpacing: "1.5px",
              display: "block",
              textAlign: "center",
              lineHeight: 1,
              textShadow: `
                1px 1px 0px #041933,
                2px 2px 0px #041933,
                3px 3px 0px #041933,
                4px 4px 0px #041933,
                5px 5px 12px rgba(0,0,0,0.3)
              `,
              transition: "none",
            }}
          >
            SOBRIETY
          </span>
        </div>

        {/* Pan Dish */}
        <Pan width={width * 0.165 * scaleSize} height={height * 0.042 * scaleSize} />
      </div>
    </AbsoluteFill>
  );
};

export default DumbbellScale;